macro.studocu.generate_md5_hash_column.macro_sql:
{% macro generate_md5_hash_column(model, column_names) -%}
    {% set column_names = column_names|default('none') %}
    {%- if var('surrogate_key_treat_nulls_as_empty_strings', False) -%}
        {%- set default_null_value = "" -%}
    {%- else -%}
        {%- set default_null_value = '_dbt_utils_surrogate_key_null_' -%}
    {%- endif -%}

    {%- set fields = [] -%}
    {%- if column_names != 'none' -%}
        {%- for column_name in column_names -%}
            {%- set columns = adapter.get_columns_in_relation(model) -%}
            {%- set column = columns | selectattr('name', 'equalto', column_name) |list  -%}

            {%- if column.data_type == 'boolean' -%}
                {%- do fields.append(
                    "CASE WHEN " ~ column_name ~ " THEN 'True' WHEN NOT " ~ column_name ~ " THEN 'False' ELSE 'Null' END"
                ) -%}
            {%- else -%}
                {%- do fields.append(
                    "coalesce(cast(" ~ column_name ~ " as " ~ dbt.type_string() ~ "), '" ~ default_null_value  ~"')"
                ) -%}
            {%- endif -%}

            {%- if not loop.last -%}
                {%- do fields.append("'-'") -%}
            {%- endif -%}
        {%- endfor -%}
    {%- else -%}
        {%- set columns = adapter.get_columns_in_relation(model) -%}
        {%- for column in columns -%}
            {%- if column.data_type == 'boolean' -%}
                {%- do fields.append(
                    "CASE WHEN " ~ column.name ~ " THEN 'True' WHEN NOT " ~ column.name ~ " THEN 'False' ELSE 'Null' END"
                ) -%}
            {%- else -%}
                {%- do fields.append(
                    "coalesce(cast(" ~ column.name ~ " as " ~ dbt.type_string() ~ "), '" ~ default_null_value  ~"')"
                ) -%}
            {%- endif -%}

            {%- if not loop.last -%}
                {%- do fields.append("'-'") -%}
            {%- endif -%}
        {%- endfor -%}
    {%- endif -%}

    {{- dbt.hash(dbt.concat(fields)) -}}

{%- endmacro %}

