macro.studocu.generate_source_yml.macro_sql:
{% macro generate_source_yml(
        schema_name,
        database_name = target.database,
        generate_columns = False,
        include_descriptions = False
    ) %}
    {% set sources_yaml = [] %}
    {% do sources_yaml.append('version: 2') %}
    {% do sources_yaml.append('') %}
    {% do sources_yaml.append('sources:') %}
    {% do sources_yaml.append(
        ' - name: ' ~ schema_name | lower
    ) %}
    {% if database_name != target.database %}
        {% do sources_yaml.append(
            ' database: ' ~ database_name | lower
        ) %}
    {% endif %}

    {% do sources_yaml.append(' tables:') %}
    {% set tables = get_tables(
        database = database_name,
        schema = schema_name
    ) %}
    {% for table in tables %}
        {% do sources_yaml.append(
            ' - name: ' ~ table | lower
        ) %}
        {% if generate_columns %}
            {% do sources_yaml.append(' columns:') %}
            {% set columns = get_columns(
                database = database_name,
                schema = schema_name,
                table = table
            ) %}
            {% for column in columns %}
                {% do sources_yaml.append(
                    ' - name: ' ~ column | lower
                ) %}
                {% if include_descriptions %}
                    {% do sources_yaml.append(
                        ' description: ""'
                    ) %}
                {% endif %}
            {% endfor %}

            {% do sources_yaml.append('') %}
