macro.studocu.url_page_group.macro_sql:
{% macro url_page_group(
        page,
        site
    ) %}
    {# Capture the page type of an URL as follow: https://domain/language/page_type/page_name/... #}
    CASE
        {# Homepage #}
        WHEN {{ page }} = {{ site }}
        OR {{ page }} = CONCAT(
            {{ site }},
            SPLIT_PART(REPLACE({{ page }}, {{ site }}, ''), '/', 1)
        )
        OR SPLIT_PART(REPLACE({{ page }}, {{ site }}, ''), '/', 2) = 'home'
        OR SPLIT_PART(REPLACE({{ page }}, {{ site }}, ''), '/', 2) IS NULL THEN 'homepage' {#  #}
        {# document, course, institution, book, messages, degree #}
        WHEN SPLIT_PART(REPLACE({{ page }}, {{ site }}, ''), '/', 2) IN (
            'document',
            'course',
            'institution',
            'book',
            'messages',
            'degree'
        ) THEN SPLIT_PART(REPLACE({{ page }}, {{ site }}, ''), '/', 2) {#  #}
        {# messages #}
        WHEN SPLIT_PART(REPLACE({{ page }}, {{ site }}, ''), '/', 2) = 'question' THEN 'messages' {#  #}
        {# blog #}
        WHEN SPLIT_PART(REPLACE({{ page }}, {{ site }}, ''), '/', 1) = 'blog'
        OR SPLIT_PART(REPLACE({{ page }}, {{ site }}, ''), '/', 2) = 'world-university-ranking' THEN 'blog' {#  #}
        {# other #}
        WHEN SPLIT_PART(REPLACE({{ page }}, {{ site }}, ''), '/', 2) IN (
            'login',
            'privacy-policy',
            'terms',
            'registration',
            'cookie-statement',
            'lottery',
            'scholarship',
            'invitation',
            'search',
            'about-us',
            'support'
        ) THEN 'other' {#  #}
        {# undefined #}
        ELSE 'undefined'
    END
{% endmacro %}

