macro.studocu.test_model_and_source_equa.macro_sql:
{%test model_and_source_equal(model, source, column="id", aggregation=false, agg_dim="", agg_metric="", agg_function="sum" ) %}

{# Only run on raw_data and ci_raw target where is located datalake schemas #}
{%- if target.name in ["raw_data", "ci_raw"] -%}    

    {% if aggregation %}
        {# Aggregation comparison #}           
        with model as (
            select
                {{ agg_dim }} as dimension,
                {{ agg_function }}({{ agg_metric }}) as metric
            from 
                {{ model }}
            group by 1
        ),
        {# Count distinct column_id in source table within the same scope/timeframe as target model #}
        {# Why? Because source data could be a real-time connection whereas model tables are refreshed on schedule #}
        source as (
            select
                {{ agg_dim }} as dimension,
                {{ agg_function }}({{ agg_metric }}) as metric
            from 
                {{ source }}
            group by 1            
        )
        select
            *
        from
            model
        left join 
            source on model.dimension = source.dimension 
        where model.metric != source.metric

    {% else %}
        {# Count distinct column_id in model table #}
        with model as (
            select
                max({{ column }}) as latest,
                count(distinct {{ column }}) as unique_rows
            from 
                {{ model }}        
        ),
        {# Count distinct column_id in source table within the same scope/timeframe as target model #}
        {# Why? Because source data could be a real-time connection whereas model tables are refreshed on schedule #}
        source as (
            select
                count(distinct {{ column }}) as unique_rows
            from 
                {{ source }}        
            where
                {{ column }} <= (select latest from model)
        )
        select
            model.unique_rows - (select unique_rows from source) rows_difference,
            case 
                when model.unique_rows > (select unique_rows from source) then 'too much in rows in raw'
                else 'missing rows'
            end as difference_type
        from
            model
        where 
            model.unique_rows != (select unique_rows from source)
    {% endif %}

{% endif %}

{% endtest %}

macro.studocu.test_mixpanel_within_sourc.macro_sql:
{% test mixpanel_within_source_interval(model, source, time_frame = '7 days', threshold = 0.01) %}
{# 
- model: target table we want to sanity check
- source: source table used as source of thruth
- time_frame: time windows to sanity check. Values: 7 days, 30 days and 12 months
- threshold: determine the size of the bandwith outside which the test will fail (float value between 0 and 1).
#}
{%- set condition -%}
    {% if time_frame == '7 days' %}
        extract(epoch from DATEADD(DAY, -7, CURRENT_DATE)) and extract(epoch from DATEADD(DAY, -1, CURRENT_DATE))
    {% elif time_frame == '30 days' %}
        extract(epoch from DATEADD(DAY, -30, CURRENT_DATE)) and extract(epoch from DATEADD(DAY, -1, CURRENT_DATE))
    {% elif time_frame == '12 months' %}
        extract(epoch from DATEADD(MONTH, -12, CURRENT_DATE)) and extract(epoch from DATEADD(DAY, -1, CURRENT_DATE))
    {% endif %}    
{%- endset -%}

    with model as (
        select
            count(distinct distinct_id) as unique_events 
        from 
            {{ model }}        
        where                
            time between {{ condition }}
    ),
    source as (
        select
            count(distinct distinct_id) as unique_events
        from 
            {{ source }}        
        where
            time between {{ condition }}     
    )
    select
        *
    from
        model
    where 
        model.unique_events not between 
            (select unique_events * (1 - {{ threshold }}) from source)
            and
            (select unique_events * (1 + {{ threshold }}) from source)              

{% endtest %}

